import { useEffect, useId, useMemo, useRef, useState, type ChangeEvent, type FormEvent, type ReactNode } from "react";
import { ArrowRight, Check, ChevronDown, Copy, Heart, LoaderCircle, Minus, Plus, Search, Truck } from "lucide-react";
import { Link, useLocation, useRoute } from "wouter";
import { collections, findCollection, findJournal, findProduct, journals, money, products, type Product } from "@/lib/catalog";
import { cartLineKey, useCommerce, wishlistProducts, type DemoOrder } from "@/lib/commerce";
import { paymentProviders, paymentRegistry, type PaymentMethod, type PaymentResult } from "@/lib/payment";
import { PageIntro } from "@/components/Storefront";
import { ProductGrid } from "@/components/ProductCard";
import { assetUrl } from "@/lib/assetUrl";

const RECENTLY_VIEWED_KEY = "usamabhanbhro-recently-viewed";
const PROMO_KEY = "usamabhanbhro-promo";
const familyOrder = ["iPhone", "Mac", "iPad", "Apple Watch", "AirPods", "Apple Vision Pro", "TV & Home", "Accessories"];
const readSearch = () => typeof window === "undefined" ? "" : new URLSearchParams(window.location.search).get("q") ?? "";
const readPromo = () => typeof window === "undefined" ? "" : window.sessionStorage.getItem(PROMO_KEY) ?? "";
const collectionHref = (category: string) => `/collections/${collections.find((collection) => collection.category === category)?.slug ?? category.toLowerCase().replaceAll(" & ", "-").replaceAll(" ", "-")}`;
const availabilityCopy = (product: Product) => product.availability === "out-of-stock" ? "Currently unavailable" : product.availability === "low-stock" ? "Low stock — order soon" : "Available now";

function recordRecentlyViewed(productId: string) {
  if (typeof window === "undefined") return;
  const prior = (window.localStorage.getItem(RECENTLY_VIEWED_KEY) ?? "").split(",").filter(Boolean);
  window.localStorage.setItem(RECENTLY_VIEWED_KEY, [productId, ...prior.filter((id) => id !== productId)].slice(0, 6).join(","));
}
function readRecentlyViewed(excludeProductId: string) {
  if (typeof window === "undefined") return [];
  const raw = window.localStorage.getItem(RECENTLY_VIEWED_KEY) ?? "";
  return raw.split(",").filter(Boolean).filter((id) => id !== excludeProductId).map((id) => products.find((item) => item.id === id)).filter(Boolean) as Product[];
}
function productFromId(id: string) { return products.find((item) => item.id === id); }

function AnimatedDisclosure({ title, children, className = "", defaultOpen = false }: { title: string; children: ReactNode; className?: string; defaultOpen?: boolean }) {
  const [open, setOpen] = useState(defaultOpen);
  const panelId = useId();
  return <section className={`animated-disclosure ${className} ${open ? "is-open" : ""}`.trim()}>
    <button type="button" className="animated-disclosure__trigger" aria-expanded={open} aria-controls={panelId} onClick={() => setOpen((value) => !value)}>{title}<ChevronDown size={16} aria-hidden="true" /></button>
    <div id={panelId} className="animated-disclosure__panel" role="region" aria-hidden={!open}><div className="animated-disclosure__panel-inner">{children}</div></div>
  </section>;
}

export function ShopPage({ collectionSlug }: { collectionSlug?: string }) {
  const collection = collectionSlug ? findCollection(collectionSlug) : undefined;
  const [, navigate] = useLocation();
  const categories = ["All", ...familyOrder.filter((item) => products.some((product) => product.category === item))];
  const [category, setCategory] = useState(collection?.category ?? "All");
  const [availability, setAvailability] = useState<"all" | "in-stock">("all");
  const [sort, setSort] = useState("featured");
  const [price, setPrice] = useState("all");
  useEffect(() => setCategory(collection?.category ?? "All"), [collection?.slug, collection?.category]);
  const items = useMemo(() => {
    let result = collection ? products.filter((product) => product.category === collection.category || product.collection === collection.name || product.collections.includes(collection.slug)) : products;
    if (category !== "All") result = result.filter((product) => product.category === category);
    if (availability === "in-stock") result = result.filter((product) => product.availability !== "out-of-stock");
    if (price === "under-500") result = result.filter((product) => product.price < 500);
    if (price === "500-1000") result = result.filter((product) => product.price >= 500 && product.price <= 1000);
    if (price === "over-1000") result = result.filter((product) => product.price > 1000);
    return [...result].sort((a, b) => {
      if (sort === "price-low") return a.price - b.price;
      if (sort === "price-high") return b.price - a.price;
      if (sort === "new") return Number(b.flags.includes("new-arrival")) - Number(a.flags.includes("new-arrival"));
      if (sort === "name") return a.name.localeCompare(b.name);
      return Number(b.flags.includes("featured") || b.flags.includes("best-seller")) - Number(a.flags.includes("featured") || a.flags.includes("best-seller"));
    });
  }, [availability, category, collection, price, sort]);
  const reset = () => { setCategory(collection?.category ?? "All"); setAvailability("all"); setPrice("all"); setSort("featured"); };
  return <><PageIntro eyebrow={collection?.eyebrow ?? "Mehronex Store"} title={collection?.name ?? "Shop Mehronex"} body={collection?.description ?? "Explore the latest Apple products, accessories, and services. Shop online with free delivery and Mehronex Store support."} />
    {collection && <div className="collection-banner"><img src={assetUrl(collection.image)} alt={`${collection.name} collection`} width={1200} height={700} loading="eager" decoding="async" /><div><p className="eyebrow eyebrow--light">{collection.name}</p><h2>Designed to work<br />beautifully together.</h2><button className="button button--light" onClick={() => navigate("/compare")}>Compare models</button></div></div>}
    <section className="listing-section"><div className="filter-bar"><div className="filter-buttons" aria-label="Product category">{categories.map((item) => <button className={category === item ? "is-active" : ""} onClick={() => setCategory(item)} key={item}>{item}</button>)}</div><div className="filter-selects"><label className="sort-control">Availability <select value={availability} onChange={(event) => setAvailability(event.target.value as "all" | "in-stock")}><option value="all">All products</option><option value="in-stock">Available now</option></select></label><label className="sort-control">Price <select value={price} onChange={(event) => setPrice(event.target.value)}><option value="all">Any price</option><option value="under-500">Under $500</option><option value="500-1000">$500–$1,000</option><option value="over-1000">Over $1,000</option></select></label><label className="sort-control">Sort <select value={sort} onChange={(event) => setSort(event.target.value)}><option value="featured">Featured</option><option value="new">New arrivals</option><option value="name">Name</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option></select></label></div></div><p className="result-count">{items.length} {items.length === 1 ? "product" : "products"} · Free delivery available</p>{items.length ? <ProductGrid key={`${category}-${availability}-${price}-${sort}`} className="catalog-grid--animated" items={items} /> : <div className="empty-state"><h2>No products match those filters.</h2><p>Try another category or clear the price and availability filters.</p><button className="button button--outline" onClick={reset}>Reset filters</button></div>}</section></>;
}

export function CollectionsPage() { return <><PageIntro eyebrow="Mehronex Store" title="Shop by product family" body="Find the product that fits your work, your creativity, your health, and your home." /><section className="collection-index">{collections.map((collection) => <Link className="collection-index__item" href={`/collections/${collection.slug}`} key={collection.slug}><img src={assetUrl(collection.image)} alt={collection.name} width={900} height={700} loading="lazy" decoding="async" /><div><p className="eyebrow">{collection.eyebrow}</p><h2>{collection.name}</h2><span className="text-link">Shop {collection.name} <ArrowRight size={13} /></span></div></Link>)}</section></>; }

export function ProductPage() {
  const [, params] = useRoute<{ slug: string }>("/products/:slug");
  const product = findProduct(params?.slug);
  const { addToCart, toggleWishlist, wishlist } = useCommerce();
  const [selectedVariant, setSelectedVariant] = useState(product?.variants[0]?.value ?? "");
  const [quantity, setQuantity] = useState(1);
  const [added, setAdded] = useState(false);
  const [recentlyViewed, setRecentlyViewed] = useState<Product[]>([]);
  const [showSticky, setShowSticky] = useState(true);
  const primaryActionRef = useRef<HTMLButtonElement>(null);
  useEffect(() => { if (!product) return; recordRecentlyViewed(product.id); setRecentlyViewed(readRecentlyViewed(product.id)); setSelectedVariant(product.variants[0]?.value ?? ""); setAdded(false); }, [product?.id]);
  useEffect(() => { const target = primaryActionRef.current; if (!target || typeof IntersectionObserver === "undefined") { setShowSticky(true); return; } const observer = new IntersectionObserver(([entry]) => setShowSticky(!entry.isIntersecting), { threshold: 0.2 }); observer.observe(target); return () => observer.disconnect(); }, [product?.id]);
  if (!product) return <NotFoundPage />;
  const selected = product.variants.find((option) => option.value === selectedVariant) ?? product.variants[0];
  const price = selected?.price ?? product.price;
  const related = product.relatedProductIds.map(productFromId).filter(Boolean) as Product[];
  const accessories = product.accessories.map(productFromId).filter(Boolean) as Product[];
  const saved = wishlist.includes(product.id);
  const canBuy = product.availability !== "out-of-stock" && Boolean(selected?.available);
  const addSelectedToCart = () => { if (!canBuy) return; addToCart(product, quantity, selectedVariant); setAdded(true); };
  return <section className="product-detail"><div className="breadcrumbs"><Link href="/shop">Shop</Link><span>/</span><Link href={collectionHref(product.category)}>{product.category}</Link><span>/</span><span>{product.name}</span></div><div className="product-detail__grid"><div className="product-gallery">{product.images.map((src, index) => <img src={assetUrl(src)} alt={`${product.name} view ${index + 1}`} width={800} height={800} loading={index === 0 ? "eager" : "lazy"} decoding="async" key={`${src}-${index}`} />)}</div><div className="product-detail__info"><p className="eyebrow">{product.category} · {product.collection}</p><h1>{product.name}</h1><p className="product-subtitle">{product.subtitle}</p><div className="product-price-row"><strong key={price} className="product-price product-price--animated">{money(price)}</strong>{product.compareAtPrice && <del>{money(product.compareAtPrice)}</del>}</div><p className="product-description">{product.description}</p><div className={`availability-panel availability-panel--${product.availability}`}><strong>{availabilityCopy(product)}</strong><span><Truck size={15} aria-hidden="true" /> Demo delivery estimate: {new Intl.DateTimeFormat("en-US", { weekday: "long", month: "short", day: "numeric" }).format(new Date(Date.now() + 4 * 86400000))}. No real delivery is scheduled.</span></div><div className="variant-selector"><span>{product.variants[0]?.label ?? "Configuration"}</span><div>{product.variants.map((option) => <button type="button" className={selectedVariant === option.value ? "is-selected" : ""} disabled={!option.available} onClick={() => setSelectedVariant(option.value)} key={option.value}>{option.value}{!option.available && " · unavailable"}</button>)}</div></div><div className="quantity-row"><span>Quantity</span><div><button aria-label="Decrease quantity" onClick={() => setQuantity(Math.max(1, quantity - 1))}><Minus size={15} aria-hidden="true" /></button><span aria-live="polite">{quantity}</span><button aria-label="Increase quantity" onClick={() => setQuantity(Math.min(10, quantity + 1))}><Plus size={15} aria-hidden="true" /></button></div></div><div className="product-actions"><button type="button" ref={primaryActionRef} className={`button button--dark product-actions__add ${added ? "is-success" : ""}`} aria-live="polite" disabled={!canBuy} onClick={addSelectedToCart}>{canBuy ? (added ? <><Check size={16} aria-hidden="true" /> Added to bag</> : "Add to bag") : "Currently unavailable"}</button><button className="button button--outline" onClick={() => toggleWishlist(product.id)}><Heart size={16} aria-hidden="true" fill={saved ? "currentColor" : "none"} />{saved ? "Saved to wishlist" : "Save to wishlist"}</button></div><div className="detail-notes">{product.details.map((detail) => <p key={detail}><Check size={14} aria-hidden="true" /><span>{detail}</span></p>)}</div><AnimatedDisclosure className="product-accordion" title="Product details" defaultOpen><div className="spec-grid">{product.specifications.map((spec) => <div key={spec.label}><span>{spec.label}</span><strong>{spec.value}</strong></div>)}</div></AnimatedDisclosure><AnimatedDisclosure className="product-accordion" title="Compatibility"><p>{product.compatibility.length ? `Designed to work with ${product.compatibility.join(", ")}.` : "See the product details above for supported configurations."}</p></AnimatedDisclosure><AnimatedDisclosure className="product-accordion" title="What’s included"><ul>{product.whatsIncluded.map((item) => <li key={item}>{item}</li>)}</ul></AnimatedDisclosure><AnimatedDisclosure className="product-accordion" title="Delivery and pickup"><p>Delivery and pickup choices are simulated at checkout for this demo. No real order, pickup, or shipment is created.</p></AnimatedDisclosure><p className="product-care"><strong>Care.</strong> {product.care}</p></div></div>{showSticky && <div className="product-sticky-cta" aria-label="Quick purchase"><div className="product-sticky-cta__meta"><span>{product.name} · {selected?.value ?? "Selected configuration"}</span><strong>{money(price)}</strong></div><button className="button button--dark" disabled={!canBuy} onClick={addSelectedToCart}>{canBuy ? (added ? "Added to bag" : "Add to bag") : "Unavailable"}</button></div>}{accessories.length > 0 && <section className="related-section"><div className="section-heading"><div><p className="eyebrow">Compatible accessories</p><h2>Complete your setup.</h2></div><Link className="text-link" href="/collections/accessories">Shop accessories <ArrowRight size={13} /></Link></div><p className="section-supporting">Accessories selected for {product.name}.</p><ProductGrid items={accessories} /></section>}{related.length > 0 && <section className="related-section related-section--secondary"><div className="section-heading"><div><p className="eyebrow">You might also like</p><h2>Keep exploring.</h2></div></div><ProductGrid items={related} /></section>}{recentlyViewed.length > 0 && <section className="related-section related-section--secondary"><div className="section-heading"><div><p className="eyebrow">Recently viewed</p><h2>Pick up where you left off.</h2></div></div><ProductGrid items={recentlyViewed} /></section>}</section>;
}

export function ComparePage() {
  const families = ["iPhone", "Mac", "iPad", "Apple Watch", "AirPods"];
  const [family, setFamily] = useState("iPhone");
  const items = products.filter((product) => product.category === family).slice(0, 4);
  const labels = Array.from(new Set(items.flatMap((item) => item.specifications.map((spec) => spec.label))));
  const rows = labels.map((label) => ({ label, values: items.map((item) => item.specifications.find((spec) => spec.label === label)?.value ?? "—") })).filter((row) => row.values.some((value) => value !== "—"));
  return <section className="compare-page"><PageIntro eyebrow="Mehronex Store" title="Compare products" body="Choose a family, compare the essentials, and find the Apple product that fits you best." /><div className="compare-tabs" role="tablist" aria-label="Product families">{families.map((item) => { const tabId = `compare-tab-${item.toLowerCase().replaceAll(" ", "-")}`; return <button id={tabId} type="button" role="tab" aria-selected={family === item} aria-controls="compare-panel" tabIndex={family === item ? 0 : -1} className={family === item ? "is-active" : ""} key={item} onClick={() => setFamily(item)}>{item}</button>; })}</div>{items.length ? <><div id="compare-panel" className="compare-table-wrap" role="tabpanel" aria-label={`${family} comparison`} tabIndex={-1}><table className="compare-table"><thead><tr><th>Feature</th>{items.map((item) => <th key={item.id}><img src={assetUrl(item.images[0])} alt="" width={400} height={400} loading="lazy" decoding="async" /><Link href={`/products/${item.slug}`}>{item.name}</Link><strong>{money(item.price)}</strong><span className="availability availability--in-stock">Available now</span></th>)}</tr></thead><tbody><tr><th>Best for</th>{items.map((item) => <td key={item.id}>{item.subtitle}</td>)}</tr>{rows.map((row) => <tr key={row.label}><th>{row.label}</th>{row.values.map((value, index) => <td key={`${row.label}-${items[index].id}`}>{value}</td>)}</tr>)}</tbody></table></div><Link className="button button--dark" href={`/products/${items[0].slug}`}>Shop {family}</Link></> : <div className="empty-state"><h2>No products to compare.</h2><p>Choose another product family.</p></div>}</section>;
}

export function SearchPage() {
  const [location, navigate] = useLocation();
  const [query, setQuery] = useState(readSearch);
  const [category, setCategory] = useState("All");
  const categories = ["All", ...familyOrder.filter((item) => products.some((product) => product.category === item))];
  useEffect(() => setQuery(readSearch()), [location]);
  const submitSearch = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const nextQuery = query.trim();
    navigate(nextQuery ? `/search?q=${encodeURIComponent(nextQuery)}` : "/search");
  };
  const clearSearch = () => { setQuery(""); setCategory("All"); navigate("/search"); };
  const results = products.filter((product) => {
    const searchable = [product.name, product.subtitle, product.description, product.category, product.family, product.collection, ...product.tags, ...product.details, ...product.features, ...product.compatibility, ...product.specifications.map((spec) => `${spec.label} ${spec.value}`), ...product.variants.map((variant) => variant.value)].join(" ").toLowerCase();
    return (category === "All" || product.category === category) && searchable.includes(query.trim().toLowerCase());
  });
  return <><PageIntro eyebrow="Mehronex Store" title="Search" body="Search products, accessories, and support topics by name, family, compatibility, or feature." /><section className="search-section"><form className="search-box" role="search" onSubmit={submitSearch}><Search size={20} aria-hidden="true" /><label className="sr-only" htmlFor="catalog-search">Search products</label><input id="catalog-search" name="q" autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search iPhone, Mac, AirPods, or accessories" aria-label="Search products" />{query && <button type="button" onClick={clearSearch} aria-label="Clear search">Clear</button>}<button type="submit">Search</button></form><div className="filter-buttons" aria-label="Search category">{categories.map((item) => <button type="button" className={category === item ? "is-active" : ""} onClick={() => setCategory(item)} key={item}>{item}</button>)}</div><p className="result-count" aria-live="polite">{query ? `${results.length} results for “${query}”` : `Browse all ${products.length} products`}</p>{results.length ? <ProductGrid key={`${query}-${category}`} className="catalog-grid--animated" items={results} /> : <div className="empty-state"><h2>No products found.</h2><p>Try iPhone, Mac, iPad, Watch, AirPods, or accessories.</p><button type="button" className="button button--outline" onClick={clearSearch}>Clear search</button></div>}</section></>;
}

function PromoField({ value, onChange }: { value: string; onChange: (value: string) => void }) { const invalid = Boolean(value && value.trim().toUpperCase() !== "APPLE10"); return <div className="promo-field"><label htmlFor="promo-code">Promo code</label><div><input id="promo-code" value={value} onChange={(event) => onChange(event.target.value)} placeholder="Try APPLE10" aria-invalid={invalid} /><span className={invalid ? "promo-error" : "promo-success"}>{invalid ? "Enter a valid code" : value ? "10% demo discount applied" : ""}</span></div></div>; }
function Summary({ subtotal, shipping, discount, promoCode, onPromoChange }: { subtotal: number; shipping: number; discount: number; promoCode: string; onPromoChange: (value: string) => void }) { return <aside className="order-summary"><p className="eyebrow">Order summary</p><div className="summary-row"><span>Subtotal</span><strong key={subtotal} className="summary-number">{money(subtotal)}</strong></div><PromoField value={promoCode} onChange={onPromoChange} />{discount > 0 && <div className="summary-row"><span>Demo discount</span><strong>−{money(discount)}</strong></div>}<div className="summary-row"><span>Delivery</span><strong>{shipping ? money(shipping) : "Free"}</strong></div><div className="summary-row summary-row--total"><span>Total</span><strong key={subtotal + shipping - discount} className="summary-number">{money(subtotal + shipping - discount)}</strong></div><Link className="button button--dark" href="/checkout">Continue to checkout</Link><p className="summary-note">This is a local demo. No payment is processed.</p></aside>; }

export function CartPage() { const { cart, subtotal, setQuantity, removeFromCart } = useCommerce(); const [promoCode, setPromoCode] = useState(readPromo); const [removingLine, setRemovingLine] = useState<string | null>(null); const removeLine = (line: { product: Product; quantity: number; variant?: string }) => { const key = cartLineKey(line); setRemovingLine(key); window.setTimeout(() => { removeFromCart(line.product.id, line.variant); setRemovingLine(null); }, 340); }; const shipping = subtotal > 0 && subtotal < 50 ? 9 : 0; const discount = promoCode.trim().toUpperCase() === "APPLE10" ? Math.round(subtotal * 0.1) : 0; const updatePromo = (value: string) => { setPromoCode(value); if (typeof window !== "undefined") window.sessionStorage.setItem(PROMO_KEY, value); }; return <section className="cart-page"><PageIntro eyebrow="Mehronex Store" title="Your bag" body="Review your products before you continue to checkout." />{cart.length ? <div className="cart-layout"><div className="cart-lines">{cart.map((line) => <div className={`cart-line ${removingLine === cartLineKey(line) ? "is-removing" : ""}`} key={cartLineKey(line)}><img src={assetUrl(line.product.images[0])} alt={line.product.name} width={160} height={160} loading="lazy" decoding="async" /><div className="cart-line__info"><p className="eyebrow">{line.product.category}</p><h2>{line.product.name}</h2><p>{line.variant ?? line.product.variants[0]?.value}</p><span className={`availability availability--${line.product.availability}`}>{availabilityCopy(line.product)}</span><div className="cart-line__actions"><button type="button" className="plain-link" disabled={removingLine === cartLineKey(line)} onClick={() => removeLine(line)}>Remove</button></div></div><div className="cart-line__controls"><div><button aria-label="Decrease quantity" onClick={() => setQuantity(line.product.id, line.quantity - 1, line.variant)}><Minus size={15} /></button><span>{line.quantity}</span><button aria-label="Increase quantity" onClick={() => setQuantity(line.product.id, line.quantity + 1, line.variant)}><Plus size={15} /></button></div><strong>{money(line.product.price * line.quantity)}</strong></div></div>)}</div><Summary subtotal={subtotal} shipping={shipping} discount={discount} promoCode={promoCode} onPromoChange={updatePromo} /></div> : <div className="empty-state"><h2>Your bag is empty.</h2><p>When you add an Apple product, it will appear here.</p><Link className="button button--dark" href="/shop">Shop Mehronex</Link></div>}</section>; }

export function AccountPage() { const { lastOrder, wishlist } = useCommerce(); return <><PageIntro eyebrow="Mehronex Store" title="Your account" body="Track your local demo order, saved products, and shopping preferences." /><section className="dashboard-grid"><div className="dashboard-card dashboard-card--dark"><p className="eyebrow eyebrow--light">Demo profile</p><h2>Demo shopper</h2><p>shopper@example.com</p><span>Local account state</span></div><div className="dashboard-card"><p className="eyebrow">Orders</p><h2>{lastOrder ? "1" : "0"}</h2><p>{lastOrder ? `Latest order ${lastOrder.id}` : "No demo orders yet"}</p><Link className="plain-link" href={lastOrder ? "/order-confirmation" : "/shop"}>{lastOrder ? "View order" : "Start shopping"}</Link></div><div className="dashboard-card"><p className="eyebrow">Saved products</p><h2>{wishlist.length}</h2><p>Products saved for later.</p><Link className="plain-link" href="/wishlist">View wishlist</Link></div><div className="dashboard-card dashboard-card--wide"><p className="eyebrow">Support</p><h2>We’re here to help.</h2><p>Get help choosing a product, setting up a device, or managing a local demo order.</p><Link className="plain-link" href="/contact">Contact support</Link></div></section></>; }

export function WishlistPage() { const { wishlist, toggleWishlist } = useCommerce(); const items = wishlistProducts(wishlist); return <><PageIntro eyebrow="Mehronex Store" title="Saved products" body="Keep products here while you compare and decide." />{items.length ? <><section className="listing-section"><ProductGrid items={items} /></section><div className="wishlist-note"><p>{items.length} saved {items.length === 1 ? "product" : "products"} · changes stay in this browser.</p><button className="plain-link" onClick={() => items.forEach((item) => toggleWishlist(item.id))}>Clear wishlist</button></div></> : <div className="empty-state"><h2>Nothing saved yet.</h2><p>Use the heart on a product card to keep it close.</p><Link className="button button--dark" href="/shop">Shop Mehronex</Link></div>}</>; }

export function JournalPage() { return <><PageIntro eyebrow="Mehronex Store guides" title="Find the right product for you." body="Compare devices, build your setup, and get more from the products you already own." /><section className="journal-index">{journals.map((journal) => <Link className="journal-index__item" href={`/journal/${journal.slug}`} key={journal.slug}><img src={assetUrl(journal.image)} alt={journal.title} width={900} height={600} loading="lazy" decoding="async" /><div><p className="eyebrow">{journal.type} · {journal.date}</p><h2>{journal.title}</h2><p>{journal.excerpt}</p><span className="text-link">Read guide <ArrowRight size={13} /></span></div></Link>)}</section></>; }
export function ArticlePage() { const [, params] = useRoute<{ slug: string }>("/journal/:slug"); const article = findJournal(params?.slug); if (!article) return <NotFoundPage />; return <article className="article-page"><div className="article-hero"><img src={assetUrl(article.image)} alt={article.title} width={1200} height={800} loading="eager" decoding="async" /><div><p className="eyebrow eyebrow--light">{article.type} · {article.date}</p><h1>{article.title}</h1></div></div><div className="article-body"><p className="article-lede">{article.excerpt}</p><p>Apple products are designed to work together. Start with the product that matters most to you, then add the accessories and services that make your everyday experience easier.</p><p>Whether you are choosing a phone, a Mac, an iPad, or a watch, compare the features that matter to your work and your life. Mehronex Store specialists can help you find the right fit.</p><blockquote>“The best product is the one that fits the way you live.”</blockquote><p>Explore the collection with the same curiosity. Notice the details, compare the options, and find the product that stays with you.</p><Link className="text-link" href="/shop">Shop Mehronex <ArrowRight size={13} /></Link></div><div className="article-related"><p className="eyebrow">Keep exploring</p><div>{journals.filter((item) => item.slug !== article.slug).map((item) => <Link href={`/journal/${item.slug}`} key={item.slug}>{item.title} <ArrowRight size={13} /></Link>)}</div></div></article>; }
export function AboutPage() { return <><PageIntro eyebrow="Mehronex Store" title="Designed to work beautifully together." body="Explore products, services, support, and shopping options in one place." /><p className="page-meta">Last updated: August 16, 2026 · This page describes a local demonstration, not a real Apple business.</p><section className="manifesto"><div className="manifesto__image"><img src={assetUrl("/sites/apple-com-7b1a/homepage-6a2c/education-start.webp")} alt="Apple products and accessories arranged in a studio composition" width={1200} height={900} loading="eager" decoding="async" /></div><div className="manifesto__copy"><p className="eyebrow">The Apple experience</p><h2>Powerful products.<br />Personal support.</h2><p>Apple products are designed around privacy, accessibility, performance, and a seamless experience across devices.</p><p>This website is a transparent commerce demonstration. Catalog, cart, wishlist, checkout, order history, and contact feedback are local to this browser; no real payment, shipment, email, or Apple support case is created.</p><Link className="text-link" href="/contact">Get support <ArrowRight size={13} /></Link></div></section></>; }
export function ContactPage() {
  const [sent, setSent] = useState(false);
  const [form, setForm] = useState({ name: "", email: "", message: "" });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const update = (key: keyof typeof form) => (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => { setForm((current) => ({ ...current, [key]: event.target.value })); setSent(false); setErrors((current) => ({ ...current, [key]: "" })); };
  const submit = (event: FormEvent) => {
    event.preventDefault();
    const next: Record<string, string> = {};
    if (!form.name.trim()) next.name = "Enter your name.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) next.email = "Enter a valid email address.";
    if (!form.message.trim()) next.message = "Tell us how we can help.";
    setErrors(next);
    if (Object.keys(next).length) { document.getElementById(`contact-${Object.keys(next)[0]}`)?.focus(); return; }
    setSent(true);
  };
  return <><PageIntro eyebrow="Mehronex Store support" title="We’re here to help." body="Ask about choosing a product, setting up a device, or navigating this local demo." /><section className="contact-layout"><form className="contact-form" onSubmit={submit} noValidate aria-describedby="contact-note"><p id="contact-note" className="demo-form-note">This is a local demo form. It does not send email or create a support ticket.</p><label htmlFor="contact-name">Name<input id="contact-name" name="name" value={form.name} onChange={update("name")} autoComplete="name" required placeholder="Your name" aria-invalid={Boolean(errors.name)} aria-describedby={errors.name ? "contact-name-error" : undefined} />{errors.name && <span id="contact-name-error" className="field-error" role="alert">{errors.name}</span>}</label><label htmlFor="contact-email">Email<input id="contact-email" name="email" value={form.email} onChange={update("email")} autoComplete="email" required type="email" placeholder="you@example.com" aria-invalid={Boolean(errors.email)} aria-describedby={errors.email ? "contact-email-error" : undefined} />{errors.email && <span id="contact-email-error" className="field-error" role="alert">{errors.email}</span>}</label><label htmlFor="contact-message">How can we help?<textarea id="contact-message" name="message" value={form.message} onChange={update("message")} autoComplete="off" required placeholder="Tell us what you need" rows={6} aria-invalid={Boolean(errors.message)} aria-describedby={errors.message ? "contact-message-error" : undefined} />{errors.message && <span id="contact-message-error" className="field-error" role="alert">{errors.message}</span>}</label><button className="button button--dark" type="submit">{sent ? <><Check size={16} aria-hidden="true" /> Message received</> : "Send message"}</button>{sent && <p className="form-success" role="status">Thanks — the demo recorded this state in the current session. No email was sent. You can continue shopping or submit another question.</p>}</form><div className="contact-aside"><p className="eyebrow">Demo support</p><h2>Online<br />In store<br />Everywhere</h2><p>Use the form for product guidance or questions about this demonstration. For shopping, browsing the catalog is the only live destination.</p><Link className="plain-link" href="/shop">Continue shopping</Link></div></section><section className="support-faq" aria-labelledby="support-faq-heading"><p className="eyebrow">Common questions</p><h2 id="support-faq-heading">Before you choose.</h2>{[["How does delivery work?", "Delivery dates and pickup choices are illustrative interface states. This demo does not dispatch a shipment or reserve store inventory."], ["Can I return a demo order?", "No real order is created, so there is nothing to return. Use the cart and checkout to review the simulated flow without entering real payment details."], ["How do I check compatibility?", "Open a product page and expand Compatibility. Catalog compatibility notes come from the local product data and are intended for exploration, not a purchase guarantee."], ["What payment methods are supported?", "Checkout offers simulated provider outcomes only. Never enter a real card number, account credential, or other financial information."]].map(([question, answer]) => <AnimatedDisclosure className="support-faq__item" title={question} key={question}><p>{answer}</p></AnimatedDisclosure>)}</section></>;
}
export function NotFoundPage() { const [, navigate] = useLocation(); const [query, setQuery] = useState(""); const submit = (event: FormEvent) => { event.preventDefault(); navigate(query.trim() ? `/search?q=${encodeURIComponent(query.trim())}` : "/search"); }; return <section className="not-found"><p className="eyebrow">404 · page not found</p><h1>We can’t find<br />that page.</h1><p>That address is not part of this storefront. Search the catalog or use one of the recovery paths below.</p><form className="not-found__search" onSubmit={submit}><label className="sr-only" htmlFor="not-found-search">Search the store</label><input id="not-found-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search products and accessories" /><button className="button button--dark" type="submit">Search</button></form><div className="not-found__actions"><Link className="button button--outline" href="/">Home</Link><Link className="button button--outline" href="/shop">Shop Mehronex</Link><Link className="plain-link" href="/collections/iphone">iPhone</Link><Link className="plain-link" href="/collections/mac">Mac</Link><Link className="plain-link" href="/collections/accessories">Accessories</Link></div></section>; }

export function PrivacyPage() { return <><PageIntro eyebrow="Privacy" title="A transparent demo, by design." body="This page explains what TechStore stores in your browser and what it does not collect." /><article className="trust-page"><p className="page-meta">Last updated: August 16, 2026</p><h2>What this demo stores</h2><p>The storefront may use your browser’s local storage and session storage to keep cart items, wishlist selections, recently viewed products, promo-code state, and the locally simulated order used by the account and confirmation pages.</p><h2>What this demo does not do</h2><p>This project does not process real payments, create shipments, send contact messages, create support tickets, or intentionally run analytics, advertising pixels, or cross-site tracking. Because no consent-requiring tracking is used by this demo, there is no cookie banner.</p><h2>Information you should not enter</h2><p>Do not enter real card numbers, financial credentials, passwords, government identifiers, or sensitive personal information into the demo checkout or contact form. The checkout is illustrative and any entered values remain within the local browser session.</p><h2>Questions</h2><p>For questions about the demonstration, use the <Link className="plain-link" href="/contact">contact page</Link>. This page is educational product documentation, not a substitute for a verified business privacy notice.</p></article></>; }
export function TermsPage() { return <><PageIntro eyebrow="Terms" title="Use the storefront as a safe demonstration." body="These plain-language terms describe the limits of the local TechStore experience." /><article className="trust-page"><p className="page-meta">Last updated: August 16, 2026</p><h2>Demo-only catalog and checkout</h2><p>Product names, images, prices, availability, delivery dates, payment outcomes, and order references are illustrative catalog data. A completed checkout does not form a sale, charge a payment method, reserve inventory, or create a delivery obligation.</p><h2>Safe use</h2><p>Use fictional information for testing. Do not attempt to submit real payment credentials or rely on this demo for product availability, compatibility, pricing, warranty, returns, or support decisions.</p><h2>Ownership and attribution</h2><p>This project is an Apple-inspired interface demonstration. It is not an Apple-operated store, and it does not claim to represent Apple or any other supplier. Product references are shown for interface exploration.</p><h2>Questions</h2><p>For questions about the demo, visit the <Link className="plain-link" href="/contact">contact page</Link>. No jurisdiction, legal entity, physical address, refund commitment, or service-level promise is asserted here because none has been verified for this demonstration.</p></article></>; }

function FieldError({ message, id }: { message?: string; id: string }) { return message ? <span id={id} className="field-error" role="alert">{message}</span> : null; }

export function CheckoutPage() {
  const { cart, subtotal, clearCart, createOrder } = useCommerce(); const [, navigate] = useLocation();
  const [method, setMethod] = useState<PaymentMethod | "">(""); const [deliveryMethod, setDeliveryMethod] = useState<"standard" | "pickup">("standard"); const [outcome, setOutcome] = useState<"success" | "failure" | "pending" | "cancelled">("success"); const [processing, setProcessing] = useState(false); const [result, setResult] = useState<PaymentResult | null>(null); const [promoCode, setPromoCode] = useState(readPromo); const [errors, setErrors] = useState<Record<string, string>>({});
  const [form, setForm] = useState({ name: "", email: "", address: "", city: "", state: "", zip: "" });
  const shipping = deliveryMethod === "pickup" || subtotal === 0 || subtotal >= 50 ? 0 : 9; const discount = promoCode.trim().toUpperCase() === "APPLE10" ? Math.round(subtotal * 0.1) : 0; const total = subtotal + shipping - discount; const provider = method ? paymentRegistry[method] : undefined;
  const update = (key: keyof typeof form) => (event: ChangeEvent<HTMLInputElement>) => { setForm((current) => ({ ...current, [key]: event.target.value })); setErrors((current) => ({ ...current, [key]: "" })); };
  const updatePromo = (value: string) => { setPromoCode(value); if (typeof window !== "undefined") window.sessionStorage.setItem(PROMO_KEY, value); };
  if (!cart.length && !result) return <section className="checkout-page commerce-state"><div className="commerce-state__stamp">MEHRONEX STORE DEMO · NO MONEY MOVED</div><PageIntro eyebrow="Checkout" title="Your bag is empty" body="Return to the shop to start your Mehronex Store demo journey." /><Link className="button button--dark" href="/shop">Browse Mehronex Store</Link></section>;
  const validate = () => { const next: Record<string, string> = {}; if (!form.name.trim()) next.name = "Enter your full name."; if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) next.email = "Enter a valid email address."; if (!form.address.trim()) next.address = "Enter a delivery address."; if (!form.city.trim()) next.city = "Enter your city."; if (!form.state.trim()) next.state = "Enter your state."; if (!/^\d{5}(-\d{4})?$/.test(form.zip.trim())) next.zip = "Enter a valid ZIP code."; if (!method) next.payment = "Choose a demo payment method."; if (promoCode && promoCode.trim().toUpperCase() !== "APPLE10") next.promo = "Enter APPLE10 or clear this field."; setErrors(next); return Object.keys(next).length === 0; };
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!validate() || !provider) return; setProcessing(true); setResult(null); const orderId = `DEMO-${Date.now()}`; const response = await provider.initialize({ amount: total, orderId, demoOutcome: outcome }); setResult(response); setProcessing(false); if (response.status === "successful" || response.status === "pending") { const order: DemoOrder = { id: `APPLE-${Date.now().toString().slice(-8)}`, date: new Date().toISOString(), items: cart, configurations: Object.fromEntries(cart.map((line) => [line.product.id, line.variant])), subtotal, discount, shipping, delivery: shipping, total, customer: { name: form.name, email: form.email }, deliveryAddress: { address: form.address, city: form.city, state: form.state, zip: form.zip }, status: response.status === "pending" ? "pending" : "confirmed", paymentMethod: provider.name, paymentStatus: response.status, referenceId: response.referenceId }; createOrder(order); clearCart(); navigate("/order-confirmation"); } };
  return <section className="checkout-page commerce-state"><div className="commerce-state__stamp">MEHRONEX STORE DEMO · NO MONEY MOVED</div><PageIntro eyebrow="Checkout" title="Review your order." body="This checkout simulates provider states locally. Never enter a real card number or financial credential." /><form className="checkout-layout" onSubmit={submit} noValidate><div className="checkout-form"><fieldset><legend>Contact</legend><label>Full name<input id="checkout-name" value={form.name} onChange={update("name")} placeholder="Amina Khan" autoComplete="name" aria-invalid={Boolean(errors.name)} aria-describedby={errors.name ? "checkout-name-error" : undefined} /><FieldError id="checkout-name-error" message={errors.name} /></label><label>Email address<input id="checkout-email" type="email" value={form.email} onChange={update("email")} placeholder="you@example.com" autoComplete="email" aria-invalid={Boolean(errors.email)} aria-describedby={errors.email ? "checkout-email-error" : undefined} /><FieldError id="checkout-email-error" message={errors.email} /></label></fieldset><fieldset><legend>Delivery address</legend><label>Address<input id="checkout-address" value={form.address} onChange={update("address")} placeholder="1 Apple Park Way" autoComplete="street-address" aria-invalid={Boolean(errors.address)} aria-describedby={errors.address ? "checkout-address-error" : undefined} /><FieldError id="checkout-address-error" message={errors.address} /></label><div className="checkout-grid"><label>City<input id="checkout-city" value={form.city} onChange={update("city")} placeholder="Cupertino" autoComplete="address-level2" aria-invalid={Boolean(errors.city)} aria-describedby={errors.city ? "checkout-city-error" : undefined} /><FieldError id="checkout-city-error" message={errors.city} /></label><label>State<input id="checkout-state" value={form.state} onChange={update("state")} placeholder="CA" autoComplete="address-level1" aria-invalid={Boolean(errors.state)} aria-describedby={errors.state ? "checkout-state-error" : undefined} /><FieldError id="checkout-state-error" message={errors.state} /></label><label>ZIP code<input id="checkout-zip" value={form.zip} onChange={update("zip")} placeholder="95014" inputMode="numeric" autoComplete="postal-code" aria-invalid={Boolean(errors.zip)} aria-describedby={errors.zip ? "checkout-zip-error" : undefined} /><FieldError id="checkout-zip-error" message={errors.zip} /></label></div><div className="delivery-choice"><span className="delivery-choice__heading">Delivery method</span><div className="delivery-choice__options"><label><input type="radio" checked={deliveryMethod === "standard"} onChange={() => setDeliveryMethod("standard")} name="delivery" /> <span><strong>Standard delivery</strong><small>{shipping ? money(shipping) : "Free"}</small></span></label><label><input type="radio" checked={deliveryMethod === "pickup"} onChange={() => setDeliveryMethod("pickup")} name="delivery" /> <span><strong>Mehronex Store pickup</strong><small>Free</small></span></label></div></div></fieldset><fieldset><legend>Payment method</legend><p className="demo-form-note">Provider connectors are simulated; no real API or credential is used.</p><div className="payment-options">{paymentProviders.map((item) => <label className={`payment-option ${method === item.id ? "is-selected" : ""}`} key={item.id}><input type="radio" name="payment" checked={method === item.id} onChange={() => { setMethod(item.id); setErrors((current) => ({ ...current, payment: "" })); }} /><span><strong>{item.name}</strong><small>{item.description}</small></span><span className="payment-option__mark">{method === item.id ? <Check size={15} /> : ""}</span></label>)}</div><FieldError id="checkout-payment-error" message={errors.payment} /><label className="demo-outcome">Demo outcome<select value={outcome} onChange={(event) => setOutcome(event.target.value as typeof outcome)}><option value="success">Successful</option><option value="pending">Pending</option><option value="failure">Failed</option><option value="cancelled">Cancelled</option></select></label></fieldset>{result && <div className={`payment-result payment-result--${result.status} state-enter`} role="alert"><strong>{result.status === "failed" ? "Payment needs attention" : `Demo payment ${result.status}`}</strong><p>{result.message}</p><small>Reference: {result.referenceId}</small>{result.status === "failed" && <div className="payment-result__actions"><button type="button" className="plain-link" onClick={() => setResult(null)}>Retry</button><button type="button" className="plain-link" onClick={() => { setResult(null); setMethod(""); }}>Choose another method</button></div>}</div>}</div><aside className="order-summary"><p className="eyebrow eyebrow--rust">Order summary</p><div className="summary-items">{cart.map((line) => <div className="summary-row summary-row--item" key={cartLineKey(line)}><span>{line.product.name} × {line.quantity}</span><strong>{money(line.product.price * line.quantity)}</strong></div>)}</div><PromoField value={promoCode} onChange={updatePromo} /><div className="summary-row"><span>Subtotal</span><strong key={subtotal} className="summary-number">{money(subtotal)}</strong></div>{discount > 0 && <div className="summary-row"><span>Demo discount</span><strong>−{money(discount)}</strong></div>}<div className="summary-row"><span>Delivery</span><strong>{shipping ? money(shipping) : "Free"}</strong></div><div className="summary-row summary-row--total"><span>Total</span><strong key={total} className="summary-number">{money(total)}</strong></div><button className="button button--dark" aria-busy={processing} disabled={processing} type="submit">{processing ? <><LoaderCircle className="button-spinner" size={16} aria-hidden="true" /> Processing demo…</> : provider ? `Place demo order · ${provider.name}` : "Choose payment method"}</button><p className="summary-note">By continuing, you acknowledge this is a non-financial showcase only.</p></aside></form></section>;
}

export function ConfirmationPage() { const { lastOrder } = useCommerce(); const [copied, setCopied] = useState(false); if (!lastOrder) return <section className="confirmation-page commerce-state"><div className="commerce-state__stamp commerce-state__stamp--rust">ORDER CONFIRMATION · LOCAL ONLY</div><p className="eyebrow eyebrow--rust">Order confirmation</p><h1>No demo order yet.</h1><p className="confirmation-lede">Complete the local checkout flow and your simulated order details will appear here. No payment is processed and no fulfillment is initiated.</p><div className="confirmation-actions"><Link className="button button--dark" href="/shop">Start shopping</Link><Link className="button button--outline" href="/cart">View your bag</Link></div></section>; const copyReference = async () => { if (!lastOrder.referenceId || !navigator.clipboard) return; await navigator.clipboard.writeText(lastOrder.referenceId); setCopied(true); }; return <section className="confirmation-page commerce-state"><div className="commerce-state__stamp commerce-state__stamp--rust">ORDER CONFIRMATION · LOCAL ONLY</div><div className="confirmation-mark"><Check size={26} aria-hidden="true" /></div><p className="eyebrow eyebrow--rust">Thank you</p><h1>Your order is<br />{lastOrder.status === "pending" ? "being reviewed." : "confirmed."}</h1><p className="confirmation-lede">Your demo order has been created locally. No payment was processed and no fulfillment has been initiated.</p><div className="confirmation-card"><dl><div><dt>Order</dt><dd>{lastOrder.id}</dd></div><div><dt>Date</dt><dd>{new Intl.DateTimeFormat("en-US", { dateStyle: "medium" }).format(new Date(lastOrder.date))}</dd></div><div><dt>Payment</dt><dd>{lastOrder.paymentMethod} · {lastOrder.paymentStatus}</dd></div><div><dt>Reference</dt><dd><span className="confirmation-reference">{lastOrder.referenceId}</span><button type="button" className="plain-link" onClick={copyReference} aria-label={`Copy order reference ${lastOrder.referenceId}`}><Copy size={14} aria-hidden="true" />{copied ? "Copied" : "Copy reference"}</button></dd></div><div><dt>Total</dt><dd>{money(lastOrder.total)}</dd></div><div><dt>Delivery</dt><dd>{lastOrder.customer.name}<br />{lastOrder.deliveryAddress.city}, {lastOrder.deliveryAddress.state}</dd></div></dl></div><div className="confirmation-items"><p className="eyebrow eyebrow--rust">Items</p>{lastOrder.items.map((line) => <div key={cartLineKey(line)}><span>{line.product.name} · {line.variant} × {line.quantity}</span><strong>{money(line.product.price * line.quantity)}</strong></div>)}</div><div className="confirmation-actions"><Link className="button button--dark" href="/shop">Continue shopping</Link><Link className="button button--outline" href="/account">View account</Link></div></section>; }
